          steps: [r`\text{Goodman: }\frac1n=\frac{100}{250}+\frac{150}{500}=0.7\Rightarrow n=1.43`, r`\text{Langer: }n_y=\frac{350}{100+150}=1.40`, r`n=\min(1.43,\,1.40)=1.40`],
